typescript.originalService:
class ProcessSaleService_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find all sales lines in current sale, and collect the sales lines item's subamount.
   *if the current sale is exist and current sale is not complete and is not ready to pay.
   *then the current sale amount is equal to the sales lines items sum subamount
   *and the current sale is ready to pay.*/
  endSale(): number {
    /*Definition Start*/
    let sLines: SalesLineItem[] = l({
      logic: () => this.CurrentSale.ContainedSalesLine,
      description: "self.CurrentSale.ContainedSalesLine",
    }).build().pass;
    let lineSubs: number[] = l({
      logic: () =>
        sLines.map(
          (o: SalesLineItem) =>
            l({
              logic: () => o.Subamount,
              description: "o.Subamount",
            }).build().pass,
        ),
      description: "sLines->collect(o:SalesLineItem|o.Subamount)",
    }).build().pass;
    let sumOfLine: number = l({
      logic: () => lineSubs.sum(),
      description: "lineSubs.sum()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(this.CurrentSale) === false,
        description: "self.CurrentSale.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.CurrentSale.IsComplete === false,
          description: "self.CurrentSale.IsComplete=false",
        })
        .and({
          logic: () => this.CurrentSale.IsReadytoPay === false,
          description: "self.CurrentSale.IsReadytoPay=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (this.CurrentSale.Amount = sumOfLine),
      description: "self.CurrentSale.Amount=sumOfLine",
    })
      .and({
        execute: () => (this.CurrentSale.IsReadytoPay = true),
        description: "self.CurrentSale.IsReadytoPay=true",
      })
      .and({
        execute: () => sumOfLine,
        description: "result=sumOfLine",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ProcessSaleService_AutoGenerated };

